script:
frappe.ui.form.on('AI Settings', {
    refresh: function(frm) {
        if (!frm.doc.monthly_budget || frm.doc.monthly_budget <= 0) return;

        frappe.call({
            method: 'custom_ui.custom_ui.api.get_current_month_cost',
            callback: function(r) {
                if (r.message !== undefined) {
                    let cost = r.message || 0;
                    let budget = frm.doc.monthly_budget;
                    let percent = (cost / budget) * 100;

                    let display_percent = percent > 100 ? 100 : percent;

                    let color = 'green';
                    if (percent > 80) color = 'orange';
                    if (percent >= 100) color = 'red';

                    let sys_currency = frappe.defaults.get_default("currency") || "USD";
                    let formatted_cost = format_currency(cost, sys_currency);
                    let formatted_budget = format_currency(budget, sys_currency);

                    frm.dashboard.set_headline(`Live AI Budget Utilized: ${formatted_cost} / ${formatted_budget}`, color);
                    frm.dashboard.add_progress('AI Budget Utilization', display_percent, `${percent.toFixed(4)}% Utilized`);

                    // Set the Percent field inline
                    if (frm.doc.budget_utilized !== display_percent) {
                        frm.set_value('budget_utilized', display_percent);
                    }
                }
            }
        });
    }
});
